interface IBaseProps {
    member: RoomMember;
    startUpdating(): void;
    stopUpdating(): void;
}

interface IAdminActionLock {
    pending: boolean;
    run(action: () => Promise<void>): Promise<void>;
}

const AdminActionLockContext = React.createContext<IAdminActionLock | null>(null);

const useAdminActionLock = (): IAdminActionLock => {
    const [pending, setPending] = useState(false);
    const inFlight = useRef(false);

    const run = useCallback(async (action: () => Promise<void>): Promise<void> => {
        // State updates can be batched, so guard synchronously as well as disabling the buttons.
        if (inFlight.current) return;
        inFlight.current = true;
        setPending(true);
        try {
            await action();
        } finally {
            inFlight.current = false;
            setPending(false);
        }
    }, []);

    return { pending, run };
};

const useMemberAdminActionLock = (): IAdminActionLock => {
    const sharedLock = useContext(AdminActionLockContext);
    const localLock = useAdminActionLock();
    return sharedLock ?? localLock;
};

const AdminActionLockProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const lock = useAdminActionLock();
    return <AdminActionLockContext.Provider value={lock}>{children}</AdminActionLockContext.Provider>;
};

const showAdminActionError = (title: string, err: unknown): void => {
    logger.error(title, err);
    Modal.createDialog(ErrorDialog, {
        title,
        description: err instanceof Error && err.message ? err.message : _t("Operation failed"),
    });
};

export const RoomKickButton = ({
    room,
    member,
    startUpdating,
    stopUpdating,
}: Omit<IBaseRoomProps, "powerLevels">): JSX.Element | null => {
    const cli = useContext(MatrixClientContext);
    const actionLock = useMemberAdminActionLock();

    // check if user can be kicked/disinvited
    if (member.membership !== "invite" && member.membership !== "join") return <></>;

    const onKick = (): Promise<void> =>
        actionLock.run(async () => {
            let updating = false;
            try {
                const commonProps = {
                    member,
                    action: room.isSpaceRoom()
                        ? member.membership === "invite"
                            ? _t("Disinvite from space")
                            : _t("Remove from space")
                        : member.membership === "invite"
                        ? _t("Disinvite from room")
                        : _t("Remove from room"),
                    title:
                        member.membership === "invite"
                            ? _t("Disinvite from %(roomName)s", { roomName: room.name })
                            : _t("Remove from %(roomName)s", { roomName: room.name }),
                    askReason: member.membership === "join",
                    danger: true,
                };

                let finished: Promise<[success?: boolean, reason?: string, rooms?: Room[]]>;

                if (room.isSpaceRoom()) {
                    ({ finished } = Modal.createDialog(
                        ConfirmSpaceUserActionDialog,
                        {
                            ...commonProps,
                            space: room,
                            spaceChildFilter: (child: Room) => {
                                // Return true if the target member is not banned and we have sufficient PL to ban them
                                const myMember = child.getMember(cli.credentials.userId || "");
                                const theirMember = child.getMember(member.userId);
                                return (
                                    !!myMember &&
                                    !!theirMember &&
                                    theirMember.membership === member.membership &&
                                    myMember.powerLevel > theirMember.powerLevel &&
                                    child.currentState.hasSufficientPowerLevelFor("kick", myMember.powerLevel)
                                );
                            },
                            allLabel: _t("Remove them from everything I'm able to"),
                            specificLabel: _t("Remove them from specific things I'm able to"),
                            warningMessage: _t("They'll still be able to access whatever you're not an admin of."),
                        },
                        "mx_ConfirmSpaceUserActionDialog_wrapper",
                    ));
                } else {
                    ({ finished } = Modal.createDialog(ConfirmUserActionDialog, commonProps));
                }

                const [proceed, reason, rooms = []] = await finished;
                if (!proceed) return;

                startUpdating();
                updating = true;
                await bulkSpaceBehaviour(room, rooms, (room) =>
                    cli.kick(room.roomId, member.userId, reason || undefined),
                );
                // Rely on the m.room.member event coming down to update the view.
                logger.log("Kick success");
            } catch (err) {
                showAdminActionError(_t("Failed to remove user"), err);
            } finally {
                if (updating) stopUpdating();
            }
        });

    const kickLabel = room.isSpaceRoom()
        ? member.membership === "invite"
            ? _t("Disinvite from space")
            : _t("Remove from space")
        : member.membership === "invite"
        ? _t("Disinvite from room")
        : _t("Remove from room");

    return (
        <AccessibleButton
            kind="link"
            className="mx_UserInfo_field mx_UserInfo_destructive"
            onClick={onKick}
            disabled={actionLock.pending}
        >
            {kickLabel}
        </AccessibleButton>
    );
};

