it("locks all member actions before kick confirmation and until the request settles", async () => {
    const confirmation = defer<[boolean, string?, Room[]?]>();
    const request = defer<{ event_id: string }>();
    const createDialogSpy = jest
        .spyOn(Modal, "createDialog")
        .mockReturnValue({ finished: confirmation.promise, close: jest.fn() });
    mockClient.kick.mockReturnValue(request.promise);
    renderComponent({ ...allActionProps, member: memberWithAllActions() });

    const kickButton = screen.getByRole("button", { name: "Remove from room" });
    act(() => {
        fireEvent.click(kickButton);
        fireEvent.click(kickButton);
        fireEvent.keyDown(kickButton, { key: "Enter", code: "Enter" });
    });

    expect(createDialogSpy).toHaveBeenCalledTimes(1);
    expect(mockClient.kick).not.toHaveBeenCalled();
    expectActionsPending(true);

    await act(async () => {
        confirmation.resolve([true]);
        await flushPromises();
    });
    expect(mockClient.kick).toHaveBeenCalledTimes(1);
    expectActionsPending(true);

    fireEvent.click(screen.getByRole("button", { name: "Ban from room" }));
    fireEvent.click(screen.getByRole("button", { name: "Mute" }));
    expect(mockClient.ban).not.toHaveBeenCalled();
    expect(mockClient.setPowerLevel).not.toHaveBeenCalled();
    expect(createDialogSpy).toHaveBeenCalledTimes(2); // Confirmation and request spinner

    await act(async () => {
        request.resolve({ event_id: "$kick" });
        await flushPromises();
    });
    expectActionsPending(false);
    expect(defaultProps.startUpdating).toHaveBeenCalledTimes(1);
    expect(defaultProps.stopUpdating).toHaveBeenCalledTimes(1);
});

it("unlocks all actions after cancelling confirmation without sending a ban", async () => {
    const confirmation = defer<[boolean, string?, Room[]?]>();
    const createDialogSpy = jest
        .spyOn(Modal, "createDialog")
        .mockReturnValue({ finished: confirmation.promise, close: jest.fn() });
    renderComponent({ ...allActionProps, member: memberWithAllActions() });

    const banButton = screen.getByRole("button", { name: "Ban from room" });
    act(() => {
        fireEvent.click(banButton);
        fireEvent.click(banButton);
    });
    expectActionsPending(true);
    expect(createDialogSpy).toHaveBeenCalledTimes(1);

    await act(async () => {
        confirmation.resolve([false]);
        await flushPromises();
    });
    expect(mockClient.ban).not.toHaveBeenCalled();
    expect(defaultProps.startUpdating).not.toHaveBeenCalled();
    expectActionsPending(false);

    fireEvent.click(screen.getByRole("button", { name: "Ban from room" }));
    expect(createDialogSpy).toHaveBeenCalledTimes(2);
});

it("shows one error and unlocks all actions when a ban fails", async () => {
    const confirmation = defer<[boolean, string?, Room[]?]>();
    const request = defer<{ event_id: string }>();
    const createDialogSpy = jest
        .spyOn(Modal, "createDialog")
        .mockReturnValue({ finished: confirmation.promise, close: jest.fn() });
    mockClient.ban.mockReturnValue(request.promise);
    renderComponent({ ...allActionProps, member: memberWithAllActions() });

    fireEvent.click(screen.getByRole("button", { name: "Ban from room" }));
    await act(async () => {
        confirmation.resolve([true]);
        await flushPromises();
    });
    expectActionsPending(true);
    expect(mockClient.ban).toHaveBeenCalledTimes(1);

    await act(async () => {
        request.reject(new Error("Permission denied"));
        await flushPromises();
    });
    expectActionsPending(false);
    expect(defaultProps.stopUpdating).toHaveBeenCalledTimes(1);
    const errors = createDialogSpy.mock.calls.filter(([dialog]) => dialog === ErrorDialog);
    expect(errors).toHaveLength(1);
    expect(errors[0][1]).toEqual(
        expect.objectContaining({ title: "Failed to ban user", description: "Permission denied" }),
    );
});

